  1	/**
  2	 * Cron-style trigger for the overdue scan.
  3	 *
  4	 * Owner D. The job emits `issue.overdue`; the notification fan-out is a
  5	 * subscriber, so this route never sends anything itself.
  6	 *
  7	 * Must call (do not reimplement): runOverdueIssueJob
  8	 */
  9	
 10	import { assertCronSecret, errorResponse } from "@/app/api/_lib/responses";
 11	import { runOverdueIssueJob } from "@/server/jobs/overdue-issue-job";
 12	
 13	export const dynamic = "force-dynamic";
 14	
 15	export async function POST(request: Request): Promise<Response> {
 16	  try {
 17	    assertCronSecret(request);
 18	
 19	    const result = await runOverdueIssueJob(new Date());
 20	    return Response.json(result);
 21	  } catch (error) {
 22	    return errorResponse(error);
 23	  }
 24	}
  1	/**
  2	 * Scans for issues past `dueAt` and emits `issue.overdue`, which the notification fan-out turns into alerts.
  3	 *
  4	 * Must call (do not reimplement): emit, shouldFilterArchived
  5	 */
  6	import { emit } from "@/lib/event-bus";
  7	import { createLogger } from "@/lib/logger";
  8	import { shouldFilterArchived } from "@/lib/soft-delete";
  9	import * as issueRepo from "@/server/repositories/issue-repository";
 10	import * as usageRepo from "@/server/repositories/usage-repository";
 11	import { toIsoTimestamp } from "@/types/common";
 12	import { runJob } from "./types";
 13	import type { JobResult } from "@/server/jobs/types";
 14	
 15	/** How many organizations one pass sweeps. */
 16	const ORG_BATCH = 50;
 17	
 18	/** Archived issues are never overdue — an archived issue has no due date. */
 19	const LIVE_ONLY = {} as const;
 20	
 21	const logger = createLogger("overdue-issue-job");
 22	
 23	/**
 24	 * Issues already announced this process's lifetime. A later sweep still
 25	 * finds a still-open, still-overdue issue — this is what keeps the job from
 26	 * re-emitting `issue.overdue` for it on every pass.
 27	 */
 28	const reported = new Set<string>();
 29	
 30	/** Test-only: clears the reported set so a fresh scenario starts empty. */
 31	export function resetOverdueTracking(): void {
 32	  reported.clear();
 33	}
 34	
 35	/**
 36	 * Publishes one `issue.overdue` per still-open, past-due issue. The job owns
 37	 * no notification logic: it announces the fact, and whoever cares (in-app
 38	 * alerts, the digest, webhooks) reacts on the bus.
 39	 */
 40	export async function runOverdueIssueJob(now: Date): Promise<JobResult> {
 41	  return runJob("overdue-issues", async (result) => {
 42	    if (!shouldFilterArchived(LIVE_ONLY)) {
 43	      logger.warn("archive scope misconfigured; skipping sweep", {});
 44	      return;
 45	    }
 46	
 47	    const stamp = toIsoTimestamp(now);
 48	    const orgIds = await usageRepo.listOrgIdsForRollup(ORG_BATCH);
 49	
 50	    for (const orgId of orgIds) {
 51	      const overdue = await issueRepo.listOverdueIssues(orgId, stamp);
 52	
 53	      for (const issue of overdue) {
 54	        if (issue.dueAt === null) continue;
 55	        if (reported.has(issue.id)) continue;
 56	
 57	        try {
 58	          await emit("issue.overdue", {
 59	            orgId,
 60	            actorId: null,
 61	            occurredAt: stamp,
 62	            issueId: issue.id,
 63	            projectId: issue.projectId,
 64	            dueAt: issue.dueAt,
 65	            assigneeId: issue.assigneeId,
 66	          });
 67	          reported.add(issue.id);
 68	          result.processed += 1;
 69	        } catch (error) {
 70	          result.failed += 1;
 71	          logger.error("failed to announce overdue issue", {
 72	            issueId: issue.id,
 73	            reason: error instanceof Error ? error.message : String(error),
 74	          });
 75	        }
 76	      }
 77	    }
 78	  });
 79	}
  1	/**
  2	 * Interval-based scheduler started from `src/instrumentation.ts`; decides which job kind is due.
  3	 */
  4	import { createLogger } from "@/lib/logger";
  5	import { drain, enqueue, pendingCount } from "./queue";
  6	import { toIsoTimestamp } from "@/types/common";
  7	import type { JobKind } from "./queue";
  8	
  9	/** How often `tick()` runs once the scheduler is started. */
 10	const TICK_INTERVAL_MS = 60_000;
 11	
 12	/** Minimum gap between two runs of the same job kind, in minutes. */
 13	const CADENCE_MINUTES: Readonly<Record<JobKind, number>> = {
 14	  "digest-email": 60,
 15	  "overdue-issues": 60,
 16	  "webhook-delivery": 1,
 17	  "usage-rollup": 15,
 18	  "search-reindex": 1_440,
 19	  "cleanup-archived": 1_440,
 20	  "trial-expiry": 360,
 21	};
 22	
 23	const logger = createLogger("job-scheduler");
 24	
 25	let timer: ReturnType<typeof setInterval> | null = null;
 26	const lastRunAt = new Map<JobKind, number>();
 27	
 28	/**
 29	 * Starts the interval. Idempotent, and `unref()`ed so a pending tick never
 30	 * keeps a process alive — a scheduler that blocks shutdown is worse than one
 31	 * that misses the last tick.
 32	 */
 33	export function startScheduler(): void {
 34	  if (timer !== null) return;
 35	
 36	  timer = setInterval(() => {
 37	    void tick(new Date()).catch((error: unknown) => {
 38	      logger.error("scheduler tick failed", {
 39	        reason: error instanceof Error ? error.message : String(error),
 40	      });
 41	    });
 42	  }, TICK_INTERVAL_MS);
 43	
 44	  timer.unref?.();
 45	  logger.info("scheduler started", { intervalMs: TICK_INTERVAL_MS });
 46	}
 47	
 48	export function stopScheduler(): void {
 49	  if (timer === null) return;
 50	  clearInterval(timer);
 51	  timer = null;
 52	  lastRunAt.clear();
 53	}
 54	
 55	export function isSchedulerRunning(): boolean {
 56	  return timer !== null;
 57	}
 58	
 59	/**
 60	 * One pass: enqueue whatever cadence says is due, then drain the queue. Split
 61	 * out from the interval so tests can drive it with an explicit clock instead
 62	 * of waiting a minute.
 63	 */
 64	export async function tick(now: Date): Promise<void> {
 65	  for (const kind of Object.keys(CADENCE_MINUTES) as JobKind[]) {
 66	    if (!isDue(kind, now)) continue;
 67	
 68	    lastRunAt.set(kind, now.getTime());
 69	    enqueue({
 70	      id: `${kind}:${Math.floor(now.getTime() / 60_000)}`,
 71	      kind,
 72	      runAt: toIsoTimestamp(now),
 73	      attempts: 0,
 74	      payload: {},
 75	    });
 76	  }
 77	
 78	  const completed = await drain();
 79	  if (completed > 0 || pendingCount() > 0) {
 80	    logger.debug("tick complete", { completed, pending: pendingCount() });
 81	  }
 82	}
 83	
 84	function isDue(kind: JobKind, now: Date): boolean {
 85	  const previous = lastRunAt.get(kind);
 86	  if (previous === undefined) return true;
 87	  return now.getTime() - previous >= CADENCE_MINUTES[kind] * 60_000;
 88	}
